716	  public async createMiddlewareFactory(
717	    requestMethod: RequestMethod,
718	  ): Promise<(path: string, callback: Function) => any> {
719	    if (!this.isMiddieRegistered) {
720	      await this.registerMiddie();
721	    }
722	    return (path: string, callback: Function) => {
723	      const hasEndOfStringCharacter = path.endsWith('$');
724	      path = hasEndOfStringCharacter ? path.slice(0, -1) : path;
725	
726	      let normalizedPath = LegacyRouteConverter.tryConvert(path);
727	
728	      // Fallback to "*path" to support plugins like GraphQL
729	      normalizedPath = normalizedPath === '/*path' ? '*path' : normalizedPath;
730	
731	      // Normalize the path to support the prefix if it set in application
732	      if (
733	        this._pathPrefix &&
734	        !normalizedPath.startsWith(this._pathPrefix) &&
735	        (normalizedPath === '/' || normalizedPath === '')
736	      ) {
737	        normalizedPath = `${this._pathPrefix}${normalizedPath}`;
738	        if (normalizedPath.endsWith('/')) {
739	          normalizedPath = `${normalizedPath}{*path}`;
740	        }
741	      }
742	
743	      try {
744	        let { regexp: re } = pathToRegexp(normalizedPath);
745	        re = hasEndOfStringCharacter
746	          ? new RegExp(re.source + '$', re.flags)
747	          : re;
748	
749	        // The following type assertion is valid as we use import('@fastify/middie') rather than require('@fastify/middie')
750	        // ref https://github.com/fastify/middie/pull/55
751	        this.instance.use(
752	          normalizedPath,
753	          (req: any, res: any, next: Function) => {
754	            const queryParamsIndex = req.originalUrl.indexOf('?');
755	            let pathname =
756	              queryParamsIndex >= 0
757	                ? req.originalUrl.slice(0, queryParamsIndex)
758	                : req.originalUrl;
759	
760	            pathname = this.sanitizeUrl(pathname);
761	
762	            if (normalizedPath) {
763	              const pathToCheck = pathname.endsWith('/')
764	                ? pathname
765	                : `${pathname}/`;
766	              if (!re.exec(pathToCheck)) {
767	                return next();
768	              }
769	            }
770	            return callback(req, res, next);
771	          },
772	        );
773	      } catch (e) {
774	        if (e instanceof TypeError) {
775	          LegacyRouteConverter.printError(path);
776	        }
777	        throw e;
778	      }
779	    };
780	  }
781	
782	  public getType(): string {
783	    return 'fastify';
784	  }
785	
786	  public isRouteOrderSensitive(): boolean {
787	    return false;
788	  }
789	
790	  public use(...args: any[]) {
791	    // Fastify requires @fastify/middie plugin to be registered before middleware can be used.
792	    // If middie is not registered yet, we queue the middleware and register it later during init.
793	    if (!this.isMiddieRegistered) {
794	      this.pendingMiddlewares.push({ args });
795	      return this;
796	    }
797	    return (this.instance.use as any)(...args);
798	  }
799	
800	  public mapException(error: unknown): unknown {
801	    if (this.isHttpFastifyError(error)) {
802	      return new HttpException(error.message, error.statusCode);
803	    }
804	
805	    return error;
806	  }
807	
808	  private isHttpFastifyError(
809	    error: any,
810	  ): error is Error & { statusCode: number } {
811	    // condition based on this code - https://github.com/fastify/fastify-error/blob/d669b150a82968322f9f7be992b2f6b463272de3/index.js#L22
812	    return (
813	      error.statusCode !== undefined &&
814	      error instanceof Error &&
815	      error.name === 'FastifyError'
816	    );
817	  }
818	
819	  protected registerWithPrefix(
820	    factory:
821	      | FastifyPluginCallback<any>
822	      | FastifyPluginAsync<any>
823	      | Promise<{ default: FastifyPluginCallback<any> }>
824	      | Promise<{ default: FastifyPluginAsync<any> }>,
825	    prefix = '/',
826	  ) {
827	    return this.instance.register(factory, { prefix });
828	  }
829	
830	  private isNativeResponse(
831	    response: TRawResponse | TReply,
832	  ): response is TRawResponse {
833	    return !('status' in response);
834	  }
835	
836	  private async closeInstance(): Promise<void> {
837	    try {
838	      await this.instance.close();
839	    } catch (err) {
840	      // Check if server is still running
841	      if (err.code !== 'ERR_SERVER_NOT_RUNNING') {
842	        throw err;
843	      }
844	    }
845	  }
846	
847	  /**
848	   * Installs a request gate in front of Fastify's routing so that, once the
849	   * shutdown has started, new requests are rejected with
850	   * "503 Service Unavailable" before they can enter the Nest pipeline
851	   * (middleware, guards, pipes, interceptors, handlers), while requests
852	   * that were already accepted run to completion.
853	   *
854	   * The gate wraps the server's "request" listener instead of using a
855	   * Fastify "onRequest" hook because Fastify's own "return503OnClosing"
856	   * fast path (enabled by default) runs before any hook and answers with a
857	   * JSON body, which would not match the Express-compatible contract (a
858	   * plain "Service Unavailable" body and a "Connection: close" header).
859	   */
860	  private installClosingRequestGate() {
861	    const server = this.httpServer as unknown as http.Server;
862	    const routing = this.instance.routing;
863	    server.removeListener('request', routing);
864	    server.on('request', (req, res) => {
865	      if (!this.isShuttingDown) {
866	        routing(req as unknown as TRawRequest, res as unknown as TRawResponse);
867	        return;
868	      }
869	      if (req.httpVersionMajor !== 2) {
870	        res.setHeader('Connection', 'close');
871	      }
872	      res.writeHead(HttpStatus.SERVICE_UNAVAILABLE, {
873	        'Content-Type': 'text/plain',
874	      });
875	      res.end('Service Unavailable');
876	    });
877	  }
878	
879	  private registerJsonContentParser(rawBody?: boolean) {
880	    const contentType = 'application/json';
881	    const withRawBody = !!rawBody;
882	    const { bodyLimit } = this.getInstance().initialConfig;
883	
884	    this.useBodyParser(
885	      contentType,
886	      withRawBody,
887	      { bodyLimit },
888	      (req, body, done) => {
889	        const { onProtoPoisoning, onConstructorPoisoning } =
890	          this.instance.initialConfig;
891	        const defaultJsonParser = this.instance.getDefaultJsonParser(
892	          onProtoPoisoning || 'error',
893	          onConstructorPoisoning || 'error',
894	        ) as FastifyBodyParser<string | Buffer, TServer>;
895	        defaultJsonParser(req, body, done);
896	      },
897	    );
898	  }
899	
900	  private registerUrlencodedContentParser(rawBody?: boolean) {
901	    const contentType = 'application/x-www-form-urlencoded';
902	    const withRawBody = !!rawBody;
903	    const { bodyLimit } = this.getInstance().initialConfig;
904	
905	    this.useBodyParser(
906	      contentType,
907	      withRawBody,
908	      { bodyLimit },
909	      (_req, body, done) => {
910	        done(null, querystringParse(body.toString()));
911	      },
912	    );
913	  }
914	
915	  private async registerMiddie() {
916	    this.isMiddieRegistered = true;
917	    await this.register(
918	      middie as unknown as Parameters<TInstance['register']>[0],
919	    );
920	  }
921	
922	  private getRequestOriginalUrl(rawRequest: TRawRequest) {
923	    return rawRequest.originalUrl || rawRequest.url!;
924	  }
925	
926	  private injectRouteOptions(
927	    routerMethodKey: Uppercase<HTTPMethods>,
928	    ...args: any[]
929	  ) {
930	    const handlerRef = args[args.length - 1];
931	    const isVersioned =
932	      !isUndefined(handlerRef.version) &&
933	      handlerRef.version !== VERSION_NEUTRAL;
934	    const routeConfig = Reflect.getMetadata(
935	      FASTIFY_ROUTE_CONFIG_METADATA,
936	      handlerRef,
937	    );
938	
939	    const routeConstraints = Reflect.getMetadata(
940	      FASTIFY_ROUTE_CONSTRAINTS_METADATA,
941	      handlerRef,
942	    );
943	
944	    const routeSchema = Reflect.getMetadata(
945	      FASTIFY_ROUTE_SCHEMA_METADATA,
946	      handlerRef,
947	    );
948	
949	    const hasConfig = !isUndefined(routeConfig);
950	    const hasConstraints = !isUndefined(routeConstraints);
951	    const hasSchema = !isUndefined(routeSchema);
952	    const routeToInject: RouteOptions<TServer, TRawRequest, TRawResponse> &
953	      RouteShorthandOptions = {
954	      method: routerMethodKey,
955	      url: args[0],
956	      handler: handlerRef,
957	    };
958	
959	    if (!this.instance.supportedMethods.includes(routerMethodKey)) {
960	      this.instance.addHttpMethod(routerMethodKey, { hasBody: true });
961	    }
962	
963	    if (isVersioned || hasConstraints || hasConfig || hasSchema) {
964	      const isPathAndRouteTuple = args.length === 2;
965	      if (isPathAndRouteTuple) {
966	        const constraints = {
967	          ...(hasConstraints && routeConstraints),
968	          ...(isVersioned && {
969	            version: handlerRef.version,
970	          }),
971	        };
972	
973	        const options = {
974	          constraints,
975	          ...(hasConfig && {
976	            config: {
977	              ...routeConfig,
978	            },
979	          }),
980	          ...(hasSchema && {
981	            schema: routeSchema,
982	          }),
983	        };
984	
985	        const routeToInjectWithOptions = { ...routeToInject, ...options };
986	
987	        return this.instance.route(routeToInjectWithOptions);
988	      }
989	    }
990	    return this.instance.route(routeToInject);
991	  }
992	
993	  /**
994	   * Fastify still accepts the router options ("ignoreTrailingSlash",
995	   * "caseSensitive", ...) at the top level, but "initialConfig.routerOptions"
996	   * only reflects them when they are passed through "routerOptions". As the
997	   * adapter always passes "routerOptions" (for the version constraint), the
998	   * top-level values are folded in so that plugins relying on
999	   * "initialConfig.routerOptions" (like @fastify/middie) normalize request
1000	   * paths exactly like the router does.
1001	   */
1002	  private getTopLevelRouterOptions(
1003	    options?: FastifyServerOptions,
1004	  ): NonNullable<FastifyServerOptions['routerOptions']> {
1005	    const routerOptions: Record<string, unknown> = {};
1006	    const routerOptionKeys = [
1007	      'ignoreTrailingSlash',
1008	      'ignoreDuplicateSlashes',
1009	      'caseSensitive',
1010	      'useSemicolonDelimiter',
1011	      'maxParamLength',
1012	      'allowUnsafeRegex',
1013	    ] as const;
1014	    for (const key of routerOptionKeys) {
1015	      if (options?.[key] !== undefined) {
1016	        routerOptions[key] = options[key];
1017	      }
1018	    }
1019	    return routerOptions;
1020	  }
1021	
1022	  private sanitizeUrl(url: string): string {
1023	    const initialConfig = this.instance.initialConfig as FastifyServerOptions;
1024	    const routerOptions =
1025	      initialConfig.routerOptions as Partial<FastifyServerOptions>;
1026	
1027	    // Absolute-form request targets ("GET http://host/path HTTP/1.1") must be
1028	    // resolved to their path before any other normalization, as the Fastify
1029	    // router does, so that middleware and routes always match the same path.
1030	    url = this.getPathFromRequestTarget(url);
1031	
1032	    if (
1033	      routerOptions.ignoreDuplicateSlashes ||
1034	      initialConfig.ignoreDuplicateSlashes
1035	    ) {
1036	      url = this.removeDuplicateSlashes(url);
1037	    }
1038	
1039	    if (
1040	      routerOptions.ignoreTrailingSlash ||
1041	      initialConfig.ignoreTrailingSlash
1042	    ) {
1043	      url = this.trimLastSlash(url);
1044	    }
1045	
1046	    if (
1047	      routerOptions.caseSensitive === false ||
1048	      initialConfig.caseSensitive === false
1049	    ) {
1050	      url = url.toLowerCase();
1051	    }
1052	    return safeDecodeURI(
1053	      url,
1054	      routerOptions.useSemicolonDelimiter ||
1055	        initialConfig.useSemicolonDelimiter,
1056	    ).path;
1057	  }
1058	
1059	  private removeDuplicateSlashes(path: string) {
1060	    const REMOVE_DUPLICATE_SLASHES_REGEXP = /\/\/+/g;
1061	    return path.indexOf('//') !== -1
1062	      ? path.replace(REMOVE_DUPLICATE_SLASHES_REGEXP, '/')
1063	      : path;
1064	  }
1065	
1066	  private trimLastSlash(path: string) {
1067	    if (path.length > 1 && path.charCodeAt(path.length - 1) === 47) {
1068	      return path.slice(0, -1);
1069	    }
1070	    return path;
1071	  }
1072	
1073	  /**
1074	   * Mirrors the absolute-form request target handling of "find-my-way".
1075	   * Returns the path of an absolute-form target ("http://host/path" -> "/path")
1076	   * and leaves any other request target untouched.
1077	   */
1078	  private getPathFromRequestTarget(url: string): string {
1079	    if (url.charCodeAt(0) === 47 /* '/' */) {
1080	      return url;
1081	    }
1082	    const schemeEnd = url.indexOf('://');
1083	    if (schemeEnd === -1) {
1084	      return url;
1085	    }
1086	    const scheme = url.slice(0, schemeEnd).toLowerCase();
1087	    if (scheme !== 'http' && scheme !== 'https') {
1088	      return url;
1089	    }
1090	    const authorityStart = schemeEnd + 3;
1091	    const pathStart = url.indexOf('/', authorityStart);
1092	    if (pathStart === authorityStart || !URL.canParse(url)) {
1093	      // Malformed target: the router rejects it before any middleware runs
1094	      return url;
1095	    }
1096	    return pathStart === -1 ? '/' : url.slice(pathStart);
1097	  }
1098	}
